with filtered as (select *, concat_ws('/', promo_code, channel) as promo_code_channel_key from promotions where ends_on > date '2024-03-11' and channel is not null), matched as (select s.*, pr.id as promo_id, pr.promo_code as promotion_promo_code, pr.discount_pct as promotion_discount_pct from filtered s left join promotions pr on s.channel = pr.channel and s.starts_on between pr.starts_on and pr.ends_on), attributed as (select a.*, pr.id as promo_id_2, pr.promo_code as promotion_promo_code_2, pr.discount_pct as promotion_discount_pct_2 from matched a left join promotions pr on a.channel <=> pr.channel and a.ends_on >= pr.starts_on and a.ends_on < pr.ends_on + interval '7' day), attributed_promotions as (select src.*, pr.id as promo_id_3, pr.promo_code as promotion_promo_code_3, pr.discount_pct as promotion_discount_pct_3 from attributed src join promotions pr on coalesce(src.channel, 'web') = pr.channel and src.ends_on >= pr.starts_on and src.ends_on <= date_add(pr.ends_on, 10)) select date_trunc('week', starts_on) as week_start, promotion_promo_code_3, count(*) as row_count, count_if(promotion_promo_code_3 = 'VIP') as vip_events, count(*) filter (where promotion_promo_code_2 = 'SPRING10') as spring10_rows from attributed_promotions group by date_trunc('week', starts_on), promotion_promo_code_3 having count(*) filter (where promotion_promo_code_2 = 'SPRING10') < 1 order by spring10_rows;
